package httpserver

import "html/template"

var dashboardTemplates = template.Must(template.New("dashboard").Parse(`
{{define "setup"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body class="login-page"><main class="login-card setup-card"><p class="eyebrow">First-run setup</p><h1>Create root administrator</h1><p class="muted">Enter the initialization code shown in the server startup logs. The code is valid only for this server process.</p>{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<form method="post" action="/dashboard/setup"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Username<input value="root" readonly aria-readonly="true"></label><label>Initialization code<input name="initializationCode" autocomplete="off" autocapitalize="none" spellcheck="false" required autofocus></label><label>Password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required><span class="field-help">Use 12–72 bytes.</span></label><label>Confirm password<input type="password" name="confirmPassword" minlength="12" maxlength="72" autocomplete="new-password" required></label><button type="submit">Create root account</button></form><p class="setup-footnote">After setup, this page is permanently disabled for this database.</p></main></body></html>{{end}}
{{define "login"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body class="login-page"><main class="login-card"><h1>DComic Sync</h1><p class="muted">Administrator dashboard</p>{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<form method="post" action="/dashboard/login"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Username<input name="username" autocomplete="username" required autofocus></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button type="submit">Sign in</button></form></main></body></html>{{end}}
{{define "overview"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic Sync</a><div><span>{{.Admin.Username}}</span><form class="inline" method="post" action="/dashboard/logout"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="link" type="submit">Sign out</button></form></div></header><main><div class="title"><div><h1>Overview</h1><p class="muted">Accounts and durable synchronization state</p></div></div>{{if .Notice}}<div class="notice">{{.Notice}}</div>{{end}}{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<section class="stats"><article><strong>{{.Stats.Users}}</strong><span>Users</span></article><article><strong>{{.Stats.Enabled}}</strong><span>Enabled</span></article><article><strong>{{.Stats.Devices}}</strong><span>Active devices</span></article><article><strong>{{.Stats.Records}}</strong><span>Records</span></article><article><strong>{{.Stats.Conflicts}}</strong><span>Conflicts</span></article></section><section class="panel"><h2>Create user</h2><form class="create-grid" method="post" action="/dashboard/users"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>Username<input name="username" minlength="3" maxlength="64" required></label><label>Initial password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button type="submit">Create</button></form></section><section class="panel"><h2>Users</h2><div class="table-wrap"><table><thead><tr><th>User</th><th>Status</th><th>Devices</th><th>Records</th><th>Conflicts</th><th>Cursor</th></tr></thead><tbody>{{range .Users}}<tr><td><a href="/dashboard/users/{{.ID}}"><strong>{{.Username}}</strong></a>{{if .Admin}} <span class="tag">admin</span>{{end}}</td><td>{{if .Disabled}}<span class="bad">Disabled</span>{{else}}<span class="good">Enabled</span>{{end}}</td><td>{{.DeviceCount}}</td><td>{{.RecordCount}}</td><td>{{.ConflictCount}}</td><td>{{.LatestCursor}}</td></tr>{{else}}<tr><td colspan="6">No users.</td></tr>{{end}}</tbody></table></div></section></main></body></html>{{end}}
{{define "user"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{.User.Username}} · DComic Sync</title><link rel="stylesheet" href="/dashboard/assets/styles.css"></head><body><header><a class="brand" href="/dashboard">DComic Sync</a><span>{{.Admin.Username}}</span></header><main><p><a href="/dashboard">← Overview</a></p><div class="title"><div><h1>{{.User.Username}}</h1><p class="muted">Created {{.User.CreatedAt.Format "2006-01-02 15:04 UTC"}}</p></div>{{if .User.Disabled}}<form method="post" action="/dashboard/users/{{.User.ID}}/enable"><input type="hidden" name="csrf" value="{{.CSRF}}"><button type="submit">Enable account</button></form>{{else}}<form method="post" action="/dashboard/users/{{.User.ID}}/disable"><input type="hidden" name="csrf" value="{{.CSRF}}"><button class="danger" type="submit">Disable account</button></form>{{end}}</div>{{if .Notice}}<div class="notice">{{.Notice}}</div>{{end}}{{if .Error}}<div class="alert">{{.Error}}</div>{{end}}<section class="stats"><article><strong>{{.User.DeviceCount}}</strong><span>Active devices</span></article><article><strong>{{.User.RecordCount}}</strong><span>Records</span></article><article><strong>{{.User.ConflictCount}}</strong><span>Conflicts</span></article><article><strong>{{.User.LatestCursor}}</strong><span>Latest cursor</span></article></section><section class="panel"><h2>Reset password</h2><p class="muted">This immediately revokes every API and dashboard session for this user.</p><form class="create-grid" method="post" action="/dashboard/users/{{.User.ID}}/password"><input type="hidden" name="csrf" value="{{.CSRF}}"><label>New password<input type="password" name="password" minlength="12" maxlength="72" autocomplete="new-password" required></label><button class="danger" type="submit">Reset and revoke</button></form></section><section class="panel"><h2>Devices</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Device ID</th><th>Last seen</th><th>Expires</th><th>Status</th><th></th></tr></thead><tbody>{{range .Devices}}<tr><td>{{.Name}}</td><td><code>{{.DeviceID}}</code></td><td>{{.LastSeen.Format "2006-01-02 15:04"}}</td><td>{{.ExpiresAt.Format "2006-01-02"}}</td><td>{{if .Revoked}}Revoked{{else}}Active{{end}}</td><td>{{if not .Revoked}}<form method="post" action="/dashboard/users/{{$.User.ID}}/devices/{{.ID}}/revoke"><input type="hidden" name="csrf" value="{{$.CSRF}}"><button class="small danger" type="submit">Revoke</button></form>{{end}}</td></tr>{{else}}<tr><td colspan="6">No devices.</td></tr>{{end}}</tbody></table></div></section><section class="panel"><h2>Sync state</h2><p>Durable records: <strong>{{.User.RecordCount}}</strong> · unresolved conflicts: <strong>{{.User.ConflictCount}}</strong> · latest cursor: <strong>{{.User.LatestCursor}}</strong></p><p class="muted">Credential payloads are never shown in the dashboard.</p></section></main></body></html>{{end}}
`))

const dashboardCSS = `:root{color-scheme:light;font-family:Inter,ui-sans-serif,system-ui,-apple-system,sans-serif;background:#f5f7fb;color:#172033}*{box-sizing:border-box}body{margin:0}a{color:#275bd8;text-decoration:none}a:hover{text-decoration:underline}header{height:64px;padding:0 max(20px,calc((100vw - 1160px)/2));display:flex;align-items:center;justify-content:space-between;background:#111a2e;color:#fff;gap:20px}.brand{font-size:1.15rem;font-weight:750;color:#fff}main{max-width:1160px;margin:0 auto;padding:28px 20px 60px}.title{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}h1{margin:0 0 4px;font-size:clamp(1.7rem,4vw,2.3rem)}h2{margin:0 0 18px;font-size:1.15rem}.muted{color:#69758b;margin:.35rem 0 1rem}.stats{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:14px;margin-bottom:22px}.stats article,.panel,.login-card{background:#fff;border:1px solid #e1e6ef;border-radius:12px;box-shadow:0 3px 14px rgba(17,26,46,.05)}.stats article{padding:18px}.stats strong{display:block;font-size:1.75rem}.stats span{color:#69758b;font-size:.87rem}.panel{padding:22px;margin-bottom:22px}.create-grid{display:grid;grid-template-columns:1fr 1.5fr auto;gap:14px;align-items:end}label{display:grid;gap:7px;font-size:.87rem;font-weight:650}input{width:100%;padding:10px 12px;border:1px solid #bac3d2;border-radius:8px;font:inherit;background:#fff}input:focus{outline:3px solid #d8e3ff;border-color:#275bd8}button{border:0;border-radius:8px;background:#275bd8;color:#fff;font:inherit;font-weight:700;padding:10px 16px;cursor:pointer}button:hover{filter:brightness(.93)}button.danger{background:#b52832}.small{padding:7px 10px;font-size:.82rem}.inline{display:inline}.link{background:transparent;padding:6px 8px;color:#bcd0ff}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:680px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e7eaf0;font-size:.9rem}th{color:#69758b;font-size:.78rem;text-transform:uppercase;letter-spacing:.04em}.tag{background:#e5ecff;color:#214da8;border-radius:99px;padding:3px 7px;font-size:.7rem}.good{color:#167044}.bad{color:#aa2630}.notice,.alert{padding:12px 14px;border-radius:8px;margin:0 0 18px}.notice{background:#e5f5ec;color:#12623b}.alert{background:#fde8ea;color:#8d2029}.login-page{min-height:100vh;display:grid;place-items:center;padding:20px;background:linear-gradient(145deg,#101a31,#274b91)}.login-card{width:min(420px,100%);padding:32px}.login-card form{display:grid;gap:18px}.login-card button{margin-top:4px}code{font-size:.82rem}@media(max-width:800px){.stats{grid-template-columns:repeat(2,1fr)}.create-grid{grid-template-columns:1fr}.title{align-items:flex-start;flex-direction:column}header{height:auto;padding-top:14px;padding-bottom:14px}}@media(max-width:420px){main{padding-left:14px;padding-right:14px}.stats{grid-template-columns:1fr 1fr}.panel{padding:16px}}`
